#!/usr/bin/env node
// Turn `packs/` into something Metro can put in the app binary.
//
// `content-pipeline.md` §4.1: "The seed packs are bundled in the app binary. On first
// launch each is **copied** to the writable documents directory and is thereafter an
// ordinary pack."
//
// Metro cannot enumerate a directory at runtime, so the enumeration happens here and is
// committed as a generated module. Two rules it encodes:
//
//   - **Word JSON is inlined.** It is ~50 KB for both packs and the first-launch copy
//     has to write the bytes somewhere; a `require` of each file gives Metro the bytes
//     without a filesystem read.
//   - **Media is an asset module, not bytes.** `require('…/x.mp3')` hands Metro the file
//     and hands the app a number it can give to `expo-audio` or `<Image source>`
//     directly, so nothing is copied and nothing is decoded twice.
//
//   node scripts/build-pack-bundle.mjs

import { readdir, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PACKS = path.join(ROOT, 'packs');
const OUT = path.join(ROOT, 'assets', 'packs');

async function listMedia(packDir) {
  const out = [];
  for (const kind of ['img', 'aud']) {
    let files;
    try { files = await readdir(path.join(packDir, 'media', kind)); } catch { continue; }
    for (const f of files.sort()) {
      if (f.startsWith('.')) continue;
      out.push(`media/${kind}/${f}`);
    }
  }
  return out;
}

async function main() {
  await mkdir(OUT, { recursive: true });
  const entries = await readdir(PACKS, { withFileTypes: true });
  const packs = entries.filter((e) => e.isDirectory()).map((e) => e.name).sort();

  const lines = [
    '// GENERATED by `node scripts/build-pack-bundle.mjs`. Do not edit.',
    '//',
    '// The seed packs, as they ship inside the binary (`content-pipeline.md` §4.1).',
    '',
    'export const BUNDLED_PACKS = {',
  ];

  for (const id of packs) {
    const dir = path.join(PACKS, id);
    let wordFiles;
    try { wordFiles = (await readdir(path.join(dir, 'words'))).filter((f) => f.endsWith('.json')).sort(); } catch { continue; }
    const media = await listMedia(dir);
    lines.push(`  '${id}': {`);
    lines.push(`    id: '${id}',`);
    lines.push(`    manifest: require('../../packs/${id}/pack.json'),`);
    lines.push('    words: {');
    for (const f of wordFiles) {
      lines.push(`      '${f}': require('../../packs/${id}/words/${f}'),`);
    }
    lines.push('    },');
    lines.push('    media: {');
    for (const ref of media) {
      lines.push(`      '${ref}': require('../../packs/${id}/${ref}'),`);
    }
    lines.push('    },');
    lines.push('  },');
  }

  lines.push('};', '');
  await writeFile(path.join(OUT, 'index.js'), lines.join('\n'));
  process.stdout.write(`  bundled ${packs.length} packs into assets/packs/index.js\n`);
}

main().catch((e) => { process.stderr.write(`${e.stack}\n`); process.exit(1); });
